def evaluate(store, task, profile, compute):
    # Owner check - must happen first
    if task['owner'] != profile['owner']:
        raise PermissionError("Owner mismatch")

    # Version check - return None if mismatch
    if task['version'] != profile['version']:
        return None

    # Build cache key with owner, profile.version, criteria_version, job_text
    key = (task['owner'], profile['version'], task['criteria_version'], task['job_text'])

    # Check store
    if key in store:
        return store[key]

    # Compute result
    try:
        result = compute()
        store[key] = result
        return result
    except Exception:
        # Exceptions propagate and are not cached
        raise

import hashlib

# Test imports
from service import evaluate

def test_owner_mismatch_raises_permission_error():
    store = {}
    task = {'owner': 'user1', 'version': 1, 'job_text': 'job1', 'criteria_version': 'v1'}
    profile = {'owner': 'user2', 'version': 1}
    compute_called = []

    def compute():
        compute_called.append(True)
        return 'result'

    try:
        evaluate(store, task, profile, compute)
        assert False, "Expected PermissionError"
    except PermissionError:
        assert len(compute_called) == 0, "compute should not be called"
        assert len(store) == 0, "store should not be modified"

    print("test_owner_mismatch_raises_permission_error passed")

def test_version_mismatch_returns_none():
    store = {'key': 'value'}
    task = {'owner': 'user1', 'version': 2, 'job_text': 'job1', 'criteria_version': 'v1'}
    profile = {'owner': 'user1', 'version': 1}
    compute_called = []

    def compute():
        compute_called.append(True)
        return 'result'

    result = evaluate(store, task, profile, compute)
    assert result is None, "Should return None"
    assert len(compute_called) == 0, "compute should not be called"
    assert len(store) == 1, "store should not be modified"
    assert store['key'] == 'value', "Existing key should be unchanged"

    print("test_version_mismatch_returns_none passed")

def test_cache_key_includes_all_fields():
    store = {}
    task = {'owner': 'user1', 'version': 1, 'job_text': 'job1', 'criteria_version': 'v1'}
    profile = {'owner': 'user1', 'version': 1}
    compute_called = []

    def compute():
        compute_called.append(True)
        return 'result'

    result = evaluate(store, task, profile, compute)
    assert result == 'result'
    assert len(compute_called) == 1
    assert len(store) == 1

    # Check the key structure
    key = list(store.keys())[0]
    assert isinstance(key, tuple)
    assert len(key) == 4
    assert key[0] == 'user1'
    assert key[1] == 1
    assert key[2] == 'v1'
    assert key[3] == 'job1'

    print("test_cache_key_includes_all_fields passed")

def test_unchanged_input_reuses_result():
    store = {}
    task = {'owner': 'user1', 'version': 1, 'job_text': 'job1', 'criteria_version': 'v1'}
    profile = {'owner': 'user1', 'version': 1}
    compute_called = []

    def compute():
        compute_called.append(True)
        return 'result'

    result1 = evaluate(store, task, profile, compute)
    assert result1 == 'result'
    assert len(compute_called) == 1

    # Same inputs but 0/None versions
    task2 = {'owner': 'user1', 'version': 0, 'job_text': 'job1', 'criteria_version': None}
    profile2 = {'owner': 'user1', 'version': None}
    compute_called2 = []

    def compute2():
        compute_called2.append(True)
        return 'result2'

    result2 = evaluate(store, task2, profile2, compute2)
    assert result2 == 'result'
    assert len(compute_called2) == 0, "Should reuse cached result with 0/None versions"

    print("test_unchanged_input_reuses_result passed")

def test_exceptions_propagate_and_not_cached():
    store = {}
    task = {'owner': 'user1', 'version': 1, 'job_text': 'job1', 'criteria_version': 'v1'}
    profile = {'owner': 'user1', 'version': 1}

    def compute():
        raise ValueError("Compute failed")

    try:
        evaluate(store, task, profile, compute)
        assert False, "Expected ValueError"
    except ValueError as e:
        assert str(e) == "Compute failed"
        assert len(store) == 0, "Exception should not be cached"

    print("test_exceptions_propagate_and_not_cached passed")

def test_owner_match_calls_compute():
    store = {}
    task = {'owner': 'user1', 'version': 1, 'job_text': 'job1', 'criteria_version': 'v1'}
    profile = {'owner': 'user1', 'version': 1}
    compute_called = []

    def compute():
        compute_called.append(True)
        return 'result'

    result = evaluate(store, task, profile, compute)
    assert result == 'result'
    assert len(compute_called) == 1
    assert len(store) == 1

    print("test_owner_match_calls_compute passed")

